var n = ["<script", ' type="application/ld+json">', "<\/script>"], g = ["<nav", ' style="', '"><a href="/"><img src="/logo_cmi.png" alt="Creative Metal Industries" width="140" height="71"></a><div style="', '"></div><a href="/blog" style="', '">\u2190 All Articles</a></nav>'], c = ["<div", ' style="', '"><a href="/" style="', '">Home</a><span style="', '">\u203A</span><a href="/blog" style="', '">Blog</a><span style="', '">\u203A</span><span>Carbon Steel Pipe Guide</span></div>'], f = ["<main", ' style="', '"><div style="', '"><span style="', '">Material Guide</span><span style="', '">June 2026 \xB7 9 min read</span><h1 style="', '">Carbon Steel Pipe, Plate, Fittings & Flanges \u2014 Complete Guide</h1><p style="', '">Carbon steel is the backbone of process piping and pressure equipment. From <strong>carbon steel pipe</strong> in <strong>ASTM A106 Gr.B</strong> to <strong>carbon steel plate</strong> in <strong>SA 516 Gr.70</strong>, plus <strong>alloy plate</strong>, <strong>carbon steel fittings</strong> and <strong>carbon steel flanges</strong> \u2014 Creative Metal Industries supplies the complete carbon and alloy steel range with full documentation from its Vadodara stockyard.</p></div><h2 style="', '">Carbon Steel Pipe \u2014 ASTM A106 Gr.B & API 5L</h2><p style="', '"><strong>Carbon steel pipe</strong> is specified by service. <strong>ASTM A106 Gr.B</strong> is the seamless carbon pipe for high-temperature service \u2014 steam lines, refinery process piping and boiler connections. ASTM A53 covers welded and seamless pipe for general and lower-temperature use, while API 5L Gr.B is the line-pipe grade for oil and gas transmission. Creative Metal Industries stocks carbon pipe from 6NB to 600NB, SCH 40 to XXS, with IBR Form III-C where the application demands it.</p><h2 style="', '">Carbon Steel Plate \u2014 SA 516 Gr.70, IS 2062 & A36</h2><p style="', '"><strong>SA 516 Gr.70</strong> is the pressure-vessel quality carbon plate for boilers, tanks, heat exchangers and pressure vessels \u2014 prized for its notch toughness at moderate and low temperatures. IS 2062 E250/E350 and ASTM A36 cover structural-grade carbon plate for general fabrication. NACE/HIC tested SA 516 Gr.70 is available for sour-service equipment. Plates run 5mm to 200mm thick and can be cut-to-size.</p><h2 style="', '">Alloy Steel Plate \u2014 ASTM A387</h2><p style="', '"><strong>Alloy plate</strong> to ASTM A387 (Grades 5, 9, 11, 12, 22, 91) is used for high-temperature pressure-vessel service where plain carbon steel loses strength. Chromium-molybdenum alloy plates resist creep and hydrogen attack in refinery reactors, hydrocrackers and boiler drums. Supplied normalised and tempered, with IBR certification available.</p><div style="', '"><table style="', '"><thead><tr style="', '"><th style="', '">Product</th><th style="', '">Grade / Spec</th><th style="', '">Typical Use</th></tr></thead><tbody>', '</tbody></table></div><h2 style="', '">Carbon Steel Fittings & Flanges</h2><p style="', '"><strong>Carbon steel fittings</strong> \u2014 buttweld elbows, tees, reducers and caps to ASTM A234 WPB (ASME B16.9), plus forged socket-weld and threaded fittings to ASTM A105 (ASME B16.11). <strong>Carbon steel flanges</strong> in A105 (and A350 LF2 for low-temperature service) cover weld-neck, slip-on, blind, SORF and SWRF types to ASME B16.5 and B16.47. Matching alloy steel fittings (WP11/WP22/WP91) and flanges (F11/F22/F91) complete high-temperature piping systems. All carry MTC and IBR Form III-C where required.</p><h2 style="', '">Applications</h2><div style="', '">', '</div><h2 style="', '">Why Source Carbon Steel from Creative Metal Industries?</h2><ul style="', '"><li><strong>Complete range:</strong> Carbon steel pipe, plate, fittings and flanges plus alloy steel grades from one source</li><li><strong>IBR Form III-C:</strong> Certified material for boiler and pressure-part applications</li><li><strong>NACE / HIC stock:</strong> Sour-service SA 516 Gr.70 plate available ready</li><li><strong>Full documentation:</strong> MTC (EN 10204 3.1/3.2) on every heat/lot</li><li><strong>Cut-to-size & dispatch:</strong> Same-day dispatch from Vadodara across Gujarat</li></ul><h2 style="', '">Frequently Asked Questions \u2014 Carbon Steel</h2><div style="', '">', '</div><div style="', '"><h2 style="', '">Need Carbon Steel Pipe, Plate, Fittings or Flanges?</h2><p style="', '">A106 Gr.B pipe, SA 516 Gr.70 plate, A234 fittings, A105 flanges. IBR & NACE certified. Vadodara stock.</p><div style="', '"><a href="tel:+919998280619" style="', '">\u{1F4DE} +91 99982 80619</a><a href="https://wa.me/919998280619" target="_blank" rel="noopener" style="', '">\u{1F4AC} WhatsApp</a><a href="/carbon-steel-pipe-fittings-vadodara" style="', '">CS Pipe & Fittings Stock \u2192</a></div></div><h3 style="', '">Related Articles & Products</h3><div style="', '">', "</div></main>"], b = ["<footer", ' style="', '"><p><strong style="', '">Creative Metal Industries</strong> \u2014 Carbon Steel Pipe, Plate, Fittings & Flanges Supplier | Vadodara, Gujarat</p><p><a href="tel:+919998280619" style="', '">+91 99982 80619</a> | <a href="https://www.creativemetalind.com" style="', '">creativemetalind.com</a></p></footer>'], u = ["<tr", ' style="', '"><td style="', '">', '</td><td style="', '">', '</td><td style="', '">', "</td></tr>"], h = ["<div", ' style="', '"><span style="', '">', '</span><h3 style="', '">', '</h3><p style="', '">', "</p></div>"], A = ["<details", ' style="', '"><summary style="', '">', '</summary><p style="', '">', "</p></details>"], y = ["<a", ' style="', '"><!--$-->', "<!--/--> \u2192</a>"];
